-- Oracle
-- Datas
DROP TABLE user2tag CASCADE CONSTRAINT;
DROP TABLE note2touite CASCADE CONSTRAINT;
DROP TABLE tag2touite CASCADE CONSTRAINT;
DROP TABLE follow CASCADE CONSTRAINT;
DROP TABLE tag CASCADE CONSTRAINT;
DROP TABLE touite CASCADE CONSTRAINT;
DROP TABLE users CASCADE CONSTRAINT;

CREATE TABLE touite (
    -- le GENERATED BY ALWAYS AS IDENTITY pour remplacer le AUTO_INCREMENT
    id NUMBER(38) GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    content varchar2(235) NOT NULL,
    note NUMBER(5),
    image_description varchar2(235),
    image_path varchar2(256),
    posted_at DATE NOT NULL,
    users_id NUMBER(11) NOT NULL
);

CREATE TABLE users (
    -- le GENERATED ALWAYS AS IDENTITY pour remplacer le AUTO_INCREMENT
    id NUMBER(11) GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    email varchar2(256) NOT NULL,
    passwd varchar2(256) NOT NULL,
    nom varchar2(100) NOT NULL,
    prenom varchar2(100) NOT NULL,
    counter_touite NUMBER(38) DEFAULT 0 NOT NULL
);

CREATE TABLE tag (
    -- le GENERATED ALWAYS AS IDENTITY pour remplacer le AUTO_INCREMENT
    id NUMBER(11) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    libelle varchar2(100) NOT NULL,
    description varchar2(256) NOT NULL
);

CREATE TABLE follow (
    follower_id NUMBER(11),
    followed_id NUMBER(11),
    PRIMARY KEY (follower_id, followed_id)
);

CREATE TABLE tag2touite (
    touite_id NUMBER(38),
    tag_id NUMBER(11),
    PRIMARY KEY (touite_id, tag_id)
);

CREATE TABLE note2touite (
    users_id NUMBER(11),
    touite_id NUMBER(38),
    -- -1 : négatif, 1 : POSITIF
    state NUMBER(1),
    PRIMARY KEY (users_id, touite_id)
);

CREATE TABLE user2tag (
    users_id NUMBER(11),
    tag_id NUMBER(11),
    PRIMARY KEY (users_id, tag_id)
);

-- Clés étrangères :
ALTER TABLE user2tag ADD FOREIGN KEY (users_id) REFERENCES users(id);
ALTER TABLE user2tag ADD FOREIGN KEY (tag_id) REFERENCES tag(id);
ALTER TABLE note2touite ADD FOREIGN KEY (users_id) REFERENCES users(id);
ALTER TABLE note2touite ADD FOREIGN KEY (touite_id) REFERENCES touite(id);
ALTER TABLE tag2touite ADD FOREIGN KEY (touite_id) REFERENCES touite(id);
ALTER TABLE tag2touite ADD FOREIGN KEY (tag_id) REFERENCES tag(id);
ALTER TABLE follow ADD FOREIGN KEY (follower_id) REFERENCES users(id);
ALTER TABLE follow ADD FOREIGN KEY (followed_id) REFERENCES users(id);
ALTER TABLE touite ADD FOREIGN KEY (users_id) REFERENCES users(id);

-- Contraintes :
ALTER TABLE users ADD CONSTRAINT uq_users_email UNIQUE (email);
ALTER TABLE tag ADD CONSTRAINT uq_tag_libelle UNIQUE (libelle);
ALTER TABLE users ADD CONSTRAINT chk_counter_touite_positiv CHECK (counter_touite >= 0);
ALTER TABLE follow ADD CONSTRAINT chk_no_self_follow CHECK (follower_id != followed_id);
ALTER TABLE note2touite ADD CONSTRAINT chk_note_bool CHECK (state IN (-1, 0, 1));

-- Déclencheurs PL/SQL
-- Mettre à jour le nombre de touites d’un utilisateur lorsqu’un touite est créé :
CREATE OR REPLACE TRIGGER count_touite_users_insert
AFTER INSERT OR UPDATE OR DELETE ON touite
FOR EACH ROW
BEGIN
    UPDATE users
    SET counter_touite = counter_touite + 1
    WHERE id = :NEW.users_id;
END;
/

CREATE OR REPLACE TRIGGER count_touite_users_delete
AFTER DELETE ON touite
FOR EACH ROW
BEGIN
    UPDATE users
    SET counter_touite = counter_touite - 1
    WHERE id = :OLD.users_id;
END;
/

-- Un utilisateur ne peut pas se suivre lui-même ou suivre un utilisateur ayant le même email :
-- (Une contrainte existe déjà)
CREATE OR REPLACE TRIGGER trigger_no_self_follow
AFTER INSERT OR UPDATE ON follow
FOR EACH ROW
DECLARE
    self_follow EXCEPTION;
BEGIN
    IF (:NEW.follower_id = :NEW.followed_id) THEN
        raise self_follow;
    END IF;

    EXCEPTION
        WHEN self_follow THEN RAISE_APPLICATION_ERROR(-20001, 'Un utilisateur ne peut pas suivre un autre utilisateur ayant le même email');
END;
/

-- Empêcher la modification de l’auteur d’un touite : une fois publié, un touite conserve son auteur initial. Il est interdit de transférer une publication à un autre utilisateur :
CREATE OR REPLACE TRIGGER not_edit_author
AFTER UPDATE ON touite
FOR EACH ROW
BEGIN
    IF (:OLD.users_id != :NEW.users_id) THEN
        RAISE_APPLICATION_ERROR(-20001, 'Il est interdit de transférer une publication à un autre utilisateur');
    END IF;
END;
/

-- Un utilisateur est limité à 50 touites par jour, pour éviter que des bots ne saturent la plateforme :
CREATE OR REPLACE TRIGGER limite_50_touites
AFTER INSERT ON touite
FOR EACH ROW
DECLARE
    -- On avait l'erreur de mutation lorsqu'on voulait parcourir la table touite pendant le trigger, du coup nous avons chercher un moyen de corriger cela et nous avons trouver ce pragma (grâce à l'IA) pour contourner ce problème
    PRAGMA AUTONOMOUS_TRANSACTION;
    nb_touite NUMBER;
BEGIN
    SELECT COUNT(*) INTO nb_touite
    FROM touite
    WHERE users_id = :NEW.users_id
    AND TRUNC(posted_at) = TRUNC(:NEW.posted_at);

    IF (nb_touite > 49) THEN
        RAISE_APPLICATION_ERROR(-20002, 'Un utilisateur ne peut pas publier plus de 50 touites par jour');
    END IF;
END;
/